## What Problem This Solves

Fixes an issue where a Comfy `workflowPath` config could point at an oversized local workflow JSON file and make OpenClaw buffer the whole file before parsing or failing.

## Why This Change Was Made

Comfy now reads workflowPath JSON through a bounded production file reader before parsing it. Inline workflow objects are unchanged, and valid workflowPath files still run through the normal Comfy provider flow.

## User Impact

Users get an early, local error for oversized Comfy workflow files instead of unbounded memory growth before any Comfy request is sent.

## Evidence

- Real call-chain proof: Comfy image generation provider runs a valid workflowPath against a local Comfy fixture and rejects an oversized workflowPath before another HTTP call.
- Focused tests: Comfy provider workflowPath happy path still submits, and oversized workflowPath is rejected before Comfy HTTP calls.

```text
$ ./node_modules/.bin/esbuild ../../outputs/local-comfy-workflow-file-cap/proof-live.ts --bundle --platform=node --format=esm --packages=external --alias:openclaw/plugin-sdk=./src/plugin-sdk --outfile=.proof-live.mjs && node .proof-live.mjs
valid: prompt=proof-prompt-1 images=1 http=3
oversized: rejected=true httpDelta=0

$ node scripts/run-vitest.mjs run extensions/comfy/image-generation-provider.test.ts extensions/comfy/workflow-runtime.test.ts
Test Files  2 passed (2)
Tests  35 passed (35)
```

<details>
<summary>proof-live.ts</summary>

```ts
import { createServer } from "node:http";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { buildComfyImageGenerationProvider } from "./extensions/comfy/image-generation-provider.ts";

const COMFY_WORKFLOW_FILE_MAX_BYTES = 16 * 1024 * 1024;

async function main() {
  const tempRoot = await mkdtemp(path.join(os.tmpdir(), "openclaw-comfy-proof-"));
  let requestCount = 0;
  const server = createServer((req, res) => {
    requestCount += 1;
    if (req.url === "/prompt") {
      res.writeHead(200, { "content-type": "application/json" });
      res.end(JSON.stringify({ prompt_id: "proof-prompt-1" }));
      return;
    }
    if (req.url === "/history/proof-prompt-1") {
      res.writeHead(200, { "content-type": "application/json" });
      res.end(
        JSON.stringify({
          "proof-prompt-1": {
            outputs: {
              "9": {
                images: [{ filename: "proof.png", subfolder: "", type: "output" }],
              },
            },
          },
        }),
      );
      return;
    }
    if (req.url === "/view?filename=proof.png&subfolder=&type=output") {
      res.writeHead(200, { "content-type": "image/png" });
      res.end("png");
      return;
    }
    res.writeHead(404);
    res.end("not found");
  });

  try {
    await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
    const address = server.address();
    if (!address || typeof address === "string") {
      throw new Error("server did not bind to a TCP port");
    }
    const baseUrl = `http://127.0.0.1:${address.port}`;
    const provider = buildComfyImageGenerationProvider();
    const workflowPath = path.join(tempRoot, "workflow.json");
    await writeFile(
      workflowPath,
      JSON.stringify({
        "6": { inputs: { text: "" } },
        "9": { inputs: {} },
      }),
      "utf8",
    );

    const valid = await provider.generateImage({
      provider: "comfy",
      model: "workflow",
      prompt: "proof prompt",
      cfg: {
        plugins: {
          entries: {
            comfy: {
              config: {
                baseUrl,
                workflowPath,
                promptNodeId: "6",
                outputNodeId: "9",
              },
            },
          },
        },
      } as never,
    });
    console.log(
      `valid: prompt=${valid.metadata.promptId} images=${valid.images.length} http=${requestCount}`,
    );

    const beforeOversizedRequests = requestCount;
    const oversizedWorkflowPath = path.join(tempRoot, "oversized-workflow.json");
    await writeFile(oversizedWorkflowPath, "x".repeat(COMFY_WORKFLOW_FILE_MAX_BYTES + 1), "utf8");
    try {
      await provider.generateImage({
        provider: "comfy",
        model: "workflow",
        prompt: "oversized proof prompt",
        cfg: {
          plugins: {
            entries: {
              comfy: {
                config: {
                  baseUrl,
                  workflowPath: oversizedWorkflowPath,
                  promptNodeId: "6",
                  outputNodeId: "9",
                },
              },
            },
          },
        } as never,
      });
      console.log("oversized: unexpected success");
      process.exitCode = 1;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.log(
        `oversized: rejected=${message.includes(`exceeds ${COMFY_WORKFLOW_FILE_MAX_BYTES} bytes`)} httpDelta=${
          requestCount - beforeOversizedRequests
        }`,
      );
    }
  } finally {
    server.close();
    await rm(tempRoot, { recursive: true, force: true });
  }
}

void main();
```

</details>

